import React from 'react';

import { useAssetHost } from 'config/api';
import { StyledFlag } from 'shared/Styles';

import {
  StyledSubCoverBadge,
  StyledSubCoverBadgeText,
  StyledSubCoverContainer,
  StyledSubCoverContent,
  StyledSubCoverHeading,
} from './SubCover.styles';

interface SubCoverProps {
  title: string;
  countryCode: string;
  countryName: string;
}

export const SubCover: React.FC<SubCoverProps> = ({
  title,
  countryCode,
  countryName,
}) => {
  const assetHost = useAssetHost();

  return (
    <StyledSubCoverContainer>
      <StyledSubCoverContent>
        <StyledSubCoverHeading>{title}</StyledSubCoverHeading>
        <StyledSubCoverBadge>
          <StyledFlag
            src={`${assetHost}/countries/rounded_flags/${countryCode}.png`}
            alt={`${countryName} flag`}
          />
          <StyledSubCoverBadgeText>
            {countryName.toUpperCase()}
          </StyledSubCoverBadgeText>
        </StyledSubCoverBadge>
      </StyledSubCoverContent>
    </StyledSubCoverContainer>
  );
};
